// @vitest-environment node
/**
 * Checks the port against fixtures generated by go-slugs (commit c3d5a69,
 * testdata/parity.json) from every string literal in its tests. Matching
 * every case gives the same titles and slugs as Zaparoo Core.
 */
import { readFileSync } from "node:fs";
import { fileURLToPath } from "node:url";
import { gunzipSync } from "node:zlib";
import { describe, expect, it } from "vitest";
import {
  browseprefix,
  filetitle,
  MediaTypeApplication,
  MediaTypeAudio,
  MediaTypeGame,
  MediaTypeImage,
  MediaTypeMovie,
  MediaTypeMusic,
  MediaTypeTVShow,
  MediaTypeVideo,
  slugifyQueryWords,
  slugifyWithTokens,
  type MediaType,
} from "../index";
import { widthFold } from "../widthFold";

type ByMediaType<T> = Partial<Record<MediaType, T>>;
type ByStrip = { false: string; true?: string };

interface ParityCase {
  input: string;
  slugs: ByMediaType<string>;
  tokens: ByMediaType<string[]>;
  queryWords: ByMediaType<string[]>;
  titles: ByMediaType<ByStrip>;
  displayTitles: ByMediaType<ByStrip>;
  stripStructuralSetMarkers: string;
  stem: string;
  prefix: { Kind: string; Rest: string };
}

interface Fixtures {
  widthFold: [number, number][];
  cases: ParityCase[];
}

const fixtures = JSON.parse(
  gunzipSync(
    readFileSync(
      fileURLToPath(new URL("../__fixtures__/parity.json.gz", import.meta.url)),
    ),
  ).toString("utf8"),
) as Fixtures;

const mediaTypes: MediaType[] = [
  MediaTypeGame,
  MediaTypeMovie,
  MediaTypeTVShow,
  MediaTypeMusic,
  MediaTypeImage,
  MediaTypeAudio,
  MediaTypeVideo,
  MediaTypeApplication,
];

// Media types the fixture lists under their own name when they differ from
// Game. "Image" stands for every other media type.
const ownParsing = new Set<MediaType>([
  MediaTypeGame,
  MediaTypeMovie,
  MediaTypeTVShow,
  MediaTypeMusic,
  MediaTypeImage,
]);

function expected<T>(values: ByMediaType<T>, mediaType: MediaType): T {
  const own = values[mediaType];
  if (own !== undefined) {
    return own;
  }
  const standIn = ownParsing.has(mediaType) ? undefined : values.Image;
  return standIn ?? values.Game!;
}

// The fixture's "Image" stand-in does not hold for Video titles: filetitle
// strips release groups for Movie, TVShow and Video. Its only other media
// type rule is the HTGDB patch suffix for Game, so Video titles equal Movie's.
function filetitleStandIn(mediaType: MediaType): MediaType {
  return mediaType === MediaTypeVideo ? MediaTypeMovie : mediaType;
}

interface Mismatch {
  input: string;
  check: string;
  want: unknown;
  got: unknown;
}

function runCase(c: ParityCase): Mismatch[] {
  const out: Mismatch[] = [];
  const check = (name: string, want: unknown, got: unknown) => {
    if (JSON.stringify(want) !== JSON.stringify(got)) {
      out.push({ input: c.input, check: name, want, got });
    }
  };

  for (const mt of mediaTypes) {
    const result = slugifyWithTokens(mt, c.input);
    check(`slug ${mt}`, expected(c.slugs, mt), result.slug);
    check(`tokens ${mt}`, expected(c.tokens, mt), result.tokens);
    check(
      `queryWords ${mt}`,
      expected(c.queryWords, mt),
      slugifyQueryWords(mt, c.input),
    );

    const titleType = filetitleStandIn(mt);
    const titles = expected(c.titles, titleType);
    const display = expected(c.displayTitles, titleType);
    for (const strip of [false, true]) {
      const key = String(strip) as "false" | "true";
      check(
        `title ${mt} strip=${key}`,
        titles[key] ?? titles.false,
        filetitle.parse(c.input, strip, mt),
      );
      check(
        `displayTitle ${mt} strip=${key}`,
        display[key] ?? display.false,
        filetitle.parseDisplay(c.input, strip, mt),
      );
    }
  }

  check(
    "stripStructuralSetMarkers",
    c.stripStructuralSetMarkers,
    filetitle.stripStructuralSetMarkers(c.input),
  );
  check("stem", c.stem, browseprefix.stemFromPath(c.input));
  const prefix = browseprefix.parseStem(c.input);
  check("prefix", c.prefix, { Kind: prefix.kind, Rest: prefix.rest });

  return out;
}

describe("go-slugs parity", () => {
  it("has the expected fixture", () => {
    expect(fixtures.cases).toHaveLength(2590);
  });

  it("matches every case", () => {
    const mismatches = fixtures.cases.flatMap(runCase);
    expect(mismatches).toEqual([]);
  });

  it("matches the width fold table for every code point", () => {
    const table = new Map(fixtures.widthFold);
    const mismatches: { codePoint: string; want: number; got: string }[] = [];
    for (let cp = 0; cp <= 0x10ffff; cp++) {
      if (cp >= 0xd800 && cp <= 0xdfff) {
        continue;
      }
      const want = table.get(cp) ?? cp;
      const got = widthFold(String.fromCodePoint(cp));
      if (got !== String.fromCodePoint(want)) {
        mismatches.push({ codePoint: cp.toString(16), want, got });
      }
    }
    expect(mismatches).toEqual([]);
  });
});
